(function(){
var allowed=['de','en','nl','fr'];
function getLang(){try{var x=localStorage.getItem('tl-language');return allowed.indexOf(x)>=0?x:'de'}catch(e){return 'de'}}
function saveLang(lang){try{localStorage.setItem('tl-language',lang)}catch(e){}}
function setCookies(lang){var value=lang==='de'?'/de/de':'/de/'+lang;document.cookie='googtrans='+value+';path=/;SameSite=Lax';document.cookie='googtrans='+value+';path=/;domain=.tante-lenchen.odpc.de;SameSite=Lax'}
function updateButtons(lang){document.querySelectorAll('[data-tl-lang]').forEach(function(b){b.setAttribute('aria-pressed',String(b.getAttribute('data-tl-lang')===lang))})}
function select(lang){if(allowed.indexOf(lang)<0)return;saveLang(lang);setCookies(lang);updateButtons(lang);var combo=document.querySelector('.goog-te-combo');if(combo&&lang!=='de'){combo.value=lang;combo.dispatchEvent(new Event('change',{bubbles:true}));return}location.reload()}
window.tlGoogleTranslateInit=function(){if(window.google&&google.translate&&google.translate.TranslateElement){new google.translate.TranslateElement({pageLanguage:'de',includedLanguages:'de,en,nl,fr',autoDisplay:false},'tl-google-translate');var tries=0;var timer=setInterval(function(){var combo=document.querySelector('.goog-te-combo');if(combo){clearInterval(timer);var lang=getLang();if(lang!=='de'&&combo.value!==lang){combo.value=lang;combo.dispatchEvent(new Event('change',{bubbles:true}))}}else if(++tries>35)clearInterval(timer)},200)}};
function boot(){var lang=getLang();setCookies(lang);updateButtons(lang);document.querySelectorAll('[data-tl-lang]').forEach(function(b){b.addEventListener('click',function(){select(b.getAttribute('data-tl-lang'))})});if(!document.getElementById('tl-google-script')){var script=document.createElement('script');script.id='tl-google-script';script.src='https://translate.google.com/translate_a/element.js?cb=tlGoogleTranslateInit';script.async=true;document.head.appendChild(script)}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
</script><details class="tl-native-menu"><summary><span aria-hidden="true">☰</span> Navigation <span class="tl-nav-chevron" aria-hidden="true">⌄</span></summary><nav id="tl-main-nav" class="nav" aria-label="Hauptnavigation"><?php foreach(['Startseite'=>'','Speisekarte'=>'speisekarte','Tisch anfragen'=>'tisch-anfragen','Kontakt'=>'kontakt','Anfahrt'=>'anfahrt','Medien & Presse'=>'medien'] as $label=>$slug){$p=$slug?get_page_by_path($slug):null;if(in_array($slug,['impressum','datenschutz'],true)&&(!$p||$p->post_status!=='publish'))continue;echo '<a href="'.esc_url(home_url('/'.($slug?$slug.'/':''))).'">'.esc_html($label).'</a>';} ?></nav></details></header><main class="wrap">